// Normalize incoming meeting request data
const body = $input.first().json.body || $input.first().json;

const title = body.title || 'Untitled Meeting';
const attendees = body.attendees || [];
const durationMinutes = parseInt(body.durationMinutes || 30, 10);
const requestedStart = body.requestedStart; // ISO string e.g. 2026-08-10T10:00:00+06:00
const requestedEnd = new Date(new Date(requestedStart).getTime() + durationMinutes * 60000).toISOString();

return [{
  json: {
    title,
    attendees,
    durationMinutes,
    requestedStart,
    requestedEnd,
    requesterEmail: body.requesterEmail || ''
  }
}];

// Merge normalized request with fetched events, then detect overlap
const request = $('Normalize Request').first().json;
const events = $input.all().map(item => item.json);

const reqStart = new Date(request.requestedStart).getTime();
const reqEnd = new Date(request.requestedEnd).getTime();

const conflicts = events.filter(ev => {
  const evStart = new Date(ev.start?.dateTime || ev.start?.date).getTime();
  const evEnd = new Date(ev.end?.dateTime || ev.end?.date).getTime();
  return reqStart < evEnd && reqEnd > evStart;
});

// Build a simple list of busy slots for the day, to help suggest free time later
const busySlots = events.map(ev => ({
  start: ev.start?.dateTime || ev.start?.date,
  end: ev.end?.dateTime || ev.end?.date,
  summary: ev.summary || ''
}));

return [{
  json: {
    ...request,
    hasConflict: conflicts.length > 0,
    conflictCount: conflicts.length,
    conflictingEvents: conflicts.map(ev => ({
      summary: ev.summary,
      start: ev.start?.dateTime || ev.start?.date,
      end: ev.end?.dateTime || ev.end?.date
    })),
    busySlots
  }
}];

 const raw = $input.first().json.content?.parts?.[0]?.text || '{}';
let parsed;
try {
  const cleaned = raw.replace(/`json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { suggestions: [] };
}

const request = $('Detect Conflict').first().json;

return [{
  json: {
    ...request,
    suggestions: parsed.suggestions || []
  }
}];

